unordered_map<long, int> first;

// Empty prefix — prefix with sum zero at conceptual position -1
first[0] = -1;

long prefix = 0;
int longest = 0;

for (int i = 0; i < n; i++) {
  prefix += arr[i];

  if (first.contains(prefix - K)) {
    int j = first[prefix - K];
    int len = i - j;
    if (len > longest) longest = len;
  }

  // Only store prefix if new — preserve the earliest occurrence of each prefix
  if (!first.contains(prefix)) first[prefix] = i;

}

return longest;
